3	/// Pure helpers for the inline terminal agent's capture path (issue #49). No libghostty here, so
4	/// the logic is unit-tested directly; the thin `ghostty_surface_*` shims live on `GhosttySurfaceView`.
5	enum TerminalCapture {
6	  /// Resolve a command's exit code. `ghostty_action_command_finished_s.exit_code` is an `Int16`
7	  /// that is `-1` when the shell did not report a status in OSC 133;D (zsh's payload-free `D`, and
8	  /// some `fish` paths). When the per-command code is absent, fall back to a known child-exit code
9	  /// (a run tab's supervisor, or a shell `exit`) if one was supplied. Returns `nil` when no code is
10	  /// known — the caller then skips diagnosis rather than guessing.
11	  static func resolveExitCode(commandFinished: Int16, childExited: Int32? = nil) -> Int32? {
12	    if commandFinished >= 0 { return Int32(commandFinished) }
13	    return childExited
14	  }
