16	  /// Post-process raw rendered text (from `ghostty_surface_read_text`) before handing it to the
17	  /// agent:
18	  /// - drop trailing blank lines (a screen selection includes the empty cells below the cursor),
19	  /// - cap to `maxBytes`, keeping the **tail** — a command's error and stack trace live at the end,
20	  /// - return `nil` when nothing meaningful remains, so the caller skips a useless diagnosis.
21	  /// The cap keeps the largest tail of **whole characters** that fits in `maxBytes`, so it never
22	  /// splits a multi-byte character (no U+FFFD) and the result's UTF-8 length is a true bound.
23	  static func tidy(_ raw: String, maxBytes: Int = 16_384) -> String? {
24	    var lines = raw.split(separator: "\n", omittingEmptySubsequences: false)
25	    while let last = lines.last, last.trimmingCharacters(in: .whitespaces).isEmpty {
26	      lines.removeLast()
27	    }
28	    let joined = lines.joined(separator: "\n")
29	    if joined.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty { return nil }
30	    guard joined.utf8.count > maxBytes else { return joined }
31	
32	    // Walk back from the end, accumulating whole characters until the next would overflow.
33	    var kept = 0
34	    var start = joined.endIndex
35	    for character in joined.reversed() {
36	      let size = String(character).utf8.count
37	      if kept + size > maxBytes { break }
38	      kept += size
39	      start = joined.index(before: start)
40	    }
41	    return start == joined.endIndex ? nil : String(joined[start...])
42	  }
43	}
